"use strict";(self.webpackChunkuxcam=self.webpackChunkuxcam||[]).push([[5797],{28839:function(e,t,s){s.r(t),s.d(t,{Head:function(){return l},default:function(){return u}});var a=s(96540),n=s(86997),r=s(54727);var o={seo:{title:"Case Study | Western Governors University",description:"How Western Governors University doubled their monthly active users",image:"https://images.ctfassets.net/vv1yxl437u7d/3Mn0AbpUmb4aFxUXNgpzY6/77b23638bee2a4c3cc29e6336ace2e1f/metaimageNEW.png"},hero:{industry:"Education",title:"How Western Governors University <span>2x'd Their Monthly Active Users</span>",description:"Western Governors University (WGU) is an online university serving more than 120,000 students across all 50 states, offering accessible and flexible higher education since 1997.",featuresUsed:[{label:"Dashboards",url:"/product-analytics/dashboards"},{label:"Funnels",url:"/product-analytics/funnels"},{label:"Session Replay",url:"/experience-analytics/session-replay"},{label:"Custom Events",url:"/product-analytics/smart-events"}],image:"/assets/images/case-study-western-governors.webp"},stats:[{value:"112% growth",label:"in monthly active users in 24 months"},{value:"145% increase",label:"in enhanced login conversions within 6 months"},{value:"242% increase",label:"in students reached over 18 months"}],challenge:{title:"The Challenge",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/1Ov4GcUZwhwz6Gdk7x9TIS/ad9823ae58f2e2026f64d865f820a987/Vector.svg",paragraphs:["WGU's product team discovered a significant problem: only 19% of the student population, about 40K users, were actively using the app. Before this, the team had been relying on guesswork and assumptions without reliable data.","The team also found that many users only had a single session and never returned.","They needed answers to key questions: Why were so few students taking advantage of the mobile app? Why did so many users fail to find value in it?"],quote:{text:'What we found was both an "Aha!" moment and a "Doh" moment. Many users, using correct credentials were getting an error message that prevented them from logging into the app. Why was this happening? That was our problem to solve.',author:"Anthony Ranallo",role:"Senior Product Manager"}},solution:{title:"The Solution",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/28xui9UzDyaFzt7EfaJuio/74b1070ae5cc420b5ac71c1dee040858/Vector.svg",paragraphs:["Using UXCam, the team filtered for users' first sessions and discovered a critical problem: many students faced login errors despite using correct credentials.",'To quantify the impact, they used <a href="/product-analytics/funnels">funnels</a> to track conversions from the login page to the home page. The findings were striking: 61% of sessions were dropping off at login. Through a combination of funnels and <a href="/experience-analytics/session-replay">session replay</a>, they validated that login was a significant barrier.','Further investigation revealed the root cause: the app only recognized "Active-status" students who had started their term. Students with portal credentials but who had not yet started were unable to log in.','To solve this, WGU adjusted the login logic to allow "cleared to start" students to access the app. While the pre-term experience was not yet built in, these students were redirected to a web view of their portal, encouraging them to return as active users.'],quote:{text:"The support and attention that our success manager gives us is one reason we continue to use the platform.",author:"Anthony Ranallo",role:"Senior Product Manager"}},whatsNext:{title:"The Result",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/Bc9n79vDsJLoV0HUy6g4j/db1b14e3e0162ced77ac4f4e7f6b5e6a/Path-7.svg",paragraphs:["The results were impressive:<ul><li>Login funnel conversion increased from 61% to 95.6%</li><li>Monthly active users grew from 55,000 to 117,000</li><li>User reach expanded to 65% of the student body from the initial 19%</li></ul>","WGU continues to track login attempts and user engagement through custom events, enabling them to proactively address issues before they escalate.","UXCam adoption is expanding across the university, with leaders and departments beyond Ed Tech using the platform for insights into user behavior."]}},i=s(17437);const l=()=>(0,i.Y)(a.Fragment,null,(0,i.Y)(r.A,{title:o.seo.title,description:o.seo.description,image:{file:{url:o.seo.image}}}),(0,i.Y)("link",{rel:"canonical",href:"https://uxcam.com/case-study/western-governors-university/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"en",href:"https://uxcam.com/case-study/western-governors-university/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"es",href:"https://uxcam.com/es/case-study/western-governors-university/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"pt-BR",href:"https://uxcam.com/br/case-study/western-governors-university/"}),(0,i.Y)("link",{rel:"alternate",hrefLang:"x-default",href:"https://uxcam.com/case-study/western-governors-university/"}));var u=()=>(0,i.Y)(n.A,{data:o})}}]);